(()=>{const article=document.getElementById('reflection'),section=document.getElementById('chapters');const stage=document.createElement('div');stage.className='theme-artwork';const c=document.createElement('canvas');c.setAttribute('aria-label','Animated symbolic artwork for the selected theme');stage.append(c);article.prepend(stage);const ctx=c.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,colors=['139,194,249','185,151,243','237,201,126'];let w=0,h=0,t=0,last=0,visible=false,mouse={x:0,y:0},busy=false;function size(){w=stage.clientWidth;h=stage.clientHeight;const d=Math.min(devicePixelRatio||1,2);c.width=w*d;c.height=h*d;ctx.setTransform(d,0,0,d,0,0)}function draw(now){const dt=Math.min(.035,(now-(last||now-16))/1000);last=now;if(!reduced)t+=dt;if(visible){ctx.clearRect(0,0,w,h);const color=colors[selected],cx=w/2+mouse.x*9,cy=h/2+mouse.y*7,scale=Math.min(w*.35,h*.35);let glow=ctx.createRadialGradient(cx,cy,0,cx,cy,scale*1.7);glow.addColorStop(0,`rgba(${color},.10)`);glow.addColorStop(1,`rgba(${color},0)`);ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.strokeStyle=`rgba(${color},.8)`;ctx.shadowColor=`rgb(${color})`;ctx.shadowBlur=12;ctx.lineWidth=1.2;if(selected===0){ctx.beginPath();for(let i=0;i<=800;i++){const a=i/800*Math.PI*2,r=scale*(.7+.22*Math.cos(3*a+t*.25)),x=cx+r*Math.cos(2*a+t*.12),y=cy+r*Math.sin(3*a)*.7; i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}else if(selected===1){for(let j=0;j<16;j++){const a=j/16*Math.PI*2,split=Math.pow((1+Math.sin(t*.65))*.5,3),r=scale+split*(12+Math.sin(j*4)*15);ctx.beginPath();ctx.arc(cx+Math.cos(a)*split*12,cy+Math.sin(a)*split*12,r,a+.018+split*.035,a+Math.PI*2/16-.018);ctx.stroke()}}else{for(let k=0;k<3;k++)for(let j=0;j<4;j++){const p=(t*.17+j/4+k*.12)%1;ctx.globalAlpha=(1-p)*.7;ctx.beginPath();ctx.ellipse(cx+(k-1)*scale*.65,cy+Math.sin(k*2)*20,p*scale,p*scale*.42,0,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1}ctx.shadowBlur=0}requestAnimationFrame(draw)}
const base=selectTheme;selectTheme=function(n){if(n===selected||reduced||section.classList.contains('theme-locked')){base(n);return}if(busy)return;busy=true;const old=selected,rect=article.getBoundingClientRect(),layer=document.createElement('canvas');layer.className='glass-fragment-layer';document.body.append(layer);const d=Math.min(devicePixelRatio||1,2);layer.width=innerWidth*d;layer.height=innerHeight*d;const g=layer.getContext('2d');g.setTransform(d,0,0,d,0,0);const snapshot=document.createElement('canvas');snapshot.width=Math.ceil(rect.width);snapshot.height=Math.ceil(rect.height);const sc=snapshot.getContext('2d');const ar=c.getBoundingClientRect();sc.drawImage(c,ar.left-rect.left,ar.top-rect.top,ar.width,ar.height);const walker=document.createTreeWalker(article,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.textContent.trim())continue;const style=getComputedStyle(node.parentElement);sc.font=style.font;sc.fillStyle=style.color;sc.textBaseline='top';const tokens=[...node.textContent.matchAll(/\S+/g)];for(const token of tokens){const range=document.createRange();range.setStart(node,token.index);range.setEnd(node,token.index+token[0].length);const r=range.getBoundingClientRect();sc.fillText(token[0],r.left-rect.left,r.top-rect.top)}}
const shards=Array.from({length:220},()=>{const x=rect.left+Math.random()*rect.width,y=rect.top+Math.random()*Math.min(rect.height,innerHeight);return{x,y,sourceX:x-rect.left,sourceY:y-rect.top,vx:(x-(rect.left+rect.width/2))*1.6+(Math.random()-.5)*220,vy:(Math.random()-.65)*450,z:Math.random(),a:Math.random()*6.28,s:5+Math.random()*18}});article.style.opacity='0';let start=performance.now(),changed=false;function fly(now){const p=(now-start)/1150;if(!changed&&p>.26){changed=true;base(n);article.style.opacity='';article.animate([{opacity:0,transform:'translateY(12px)',filter:'blur(4px)'},{opacity:1,transform:'none',filter:'none'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)'})}g.clearRect(0,0,innerWidth,innerHeight);for(const s of shards){const x=s.x+s.vx*p,y=s.y+s.vy*p+150*p*p,a=s.a+p*(s.z-.5)*8,scale=1+p*s.z;g.save();g.translate(x,y);g.rotate(a);g.scale(scale,Math.max(.08,Math.abs(Math.cos(p*5+s.a))));g.fillStyle=`rgba(${colors[old]},${Math.max(0,1-p)*.16})`;g.strokeStyle=`rgba(${colors[old]},${Math.max(0,1-p)*.7})`;g.lineWidth=.6;g.beginPath();g.moveTo(-s.s,-s.s*.5);g.lineTo(s.s*.8,-s.s*.3);g.lineTo(s.s*.3,s.s);g.closePath();g.fill();g.save();g.clip();g.globalAlpha=Math.max(0,1-p);g.drawImage(snapshot,-s.sourceX,-s.sourceY);g.restore();g.stroke();g.restore()}if(p<1)requestAnimationFrame(fly);else{layer.remove();busy=false}}requestAnimationFrame(fly)};stage.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect();mouse.x=(e.clientX-r.left)/w-.5;mouse.y=(e.clientY-r.top)/h-.5});stage.addEventListener('pointerleave',()=>mouse={x:0,y:0});new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(stage);addEventListener('resize',size);size();requestAnimationFrame(draw)})();
